        display: 'flex',
        flexDirection: 'column',
        gap: 4,
      }}
    >
      {bench.length === 0 && <span style={{ fontSize: 12, color: '#666' }}>Drop players here</span>}
      {bench.map(id => {
        const p = players.find(pl => pl.id === id)
        return p ? <PlayerJersey key={p.id} player={p} size="small" /> : null
      })}
    </div>
  )
}

