import { useDraggable } from '@dnd-kit/core'
import { Player } from '../types'

interface Props {
  player: Player
  size?: 'small' | 'pitch'
}

export default function PlayerJersey({ player, size = 'small' }: Props) {
  const { attributes, listeners, setNodeRef, transform } = useDraggable({ id: player.id })

