        photoURL = await getDownloadURL(snapshot.ref)
      } else if (removePhoto) {
        photoURL = null
      }
      const data: Record<string, unknown> = { name }
      if (photoURL !== undefined) data.photoURL = photoURL || ''
      await updateDoc(doc(db, 'coaches', editId), data)
      setShowModal(false)
    } catch (err) {
      console.error(err)
      alert('Error saving.')
    }
    setUploading(false)
  }

