args.new_str:
const handleShare = async () => {
  if (!pitchRef.current) return
  try {
    // Convert cross-origin images to base64 before screenshot
    const images = pitchRef.current.querySelectorAll('img')
    const originals: { img: HTMLImageElement; src: string }[] = []
    for (const img of images) {
      if (img.src && !img.src.startsWith('data:')) {
        try {
          const resp = await fetch(img.src, { mode: 'cors' })
          const blob = await resp.blob()
          const dataUrl = await new Promise<string>(resolve => {
            const reader = new FileReader()
            reader.onloadend = () => resolve(reader.result as string)
            reader.readAsDataURL(blob)
          })
          originals.push({ img, src: img.src })
          img.src = dataUrl
        } catch {
          // Skip if can't fetch
        }
      }
    }

    // Disable 3D for screenshot
    const pitchDiv = pitchRef.current.querySelector('[data-pitch]') as HTMLElement | null
    if (pitchDiv) pitchDiv.style.transform = 'none'

    const dataUrl = await toPng(pitchRef.current, {
      backgroundColor: '#111',
      pixelRatio: 2,
      skipFonts: true,
    })

    // Restore
    if (pitchDiv) pitchDiv.style.transform = 'rotateX(4deg)'
    originals.forEach(({ img, src }) => { img.src = src })

    const blob = await (await fetch(dataUrl)).blob()
    const file = new File([blob], `lineup-${matchDate}.png`, { type: 'image/png' })
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ text: `Lineup vs ${opponent || 'TBD'} (${matchDate})`, files: [file] })
    } else {
      const a = document.createElement('a')
      a.href = dataUrl
      a.download = `lineup-vs-${opponent || 'TBD'}-${matchDate}.png`
      a.click()
      window.open(`https://web.whatsapp.com/send?text=${encodeURIComponent(`Lineup vs ${opponent || 'TBD'} (${matchDate})`)}`, '_blank')
    }
  } catch (err) {
    console.error('Share error:', err)
    alert('Could not generate image. Try on a different browser or device.')

